insert into public.recipes (slug, title, tagline, cuisine, meal_types, emoji, base_servings, prep_minutes, cook_minutes, difficulty, ingredients, steps, calories, protein, carbs, fat, fiber, tags, prep_friendly, lily_note) values
('chicken-olive-tagine-potatoes','Chicken & Olive Tagine','Lemony chicken with potatoes and green olives','Moroccan','{lunch,dinner}','🍗',2,10,35,'easy',
 '[{"name":"Chicken legs","amount":"400 g","category":"Meat"},{"name":"Potatoes","amount":"400 g","category":"Produce"},{"name":"Onion","amount":"1 pc","category":"Produce"},{"name":"Green olives","amount":"60 g","category":"Pantry"},{"name":"Lemon","amount":"1 pc","category":"Produce"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Garlic","amount":"2 pc","category":"Produce"},{"name":"Ras el hanout","amount":"8 g","category":"Spices"},{"name":"Water","amount":"250 ml","category":"Pantry"}]'::jsonb,
 '["Soften the sliced onion and garlic in the oil in a wide pan, 5 minutes.","Add the chicken and ras el hanout, turn until coated and golden.","Add the potato chunks, water and a pinch of salt. Cover and simmer 25 minutes.","Stir in the olives and lemon juice, uncover and let the sauce thicken 5 minutes."]'::jsonb,
 520,42,44,20,6,'{"one pot","budget"}',true,'The sauce is the best bit — keep a piece of khobz nearby.'),
('kefta-meatball-tagine','Kefta Meatball Tagine','Minced beef meatballs in tomato with eggs','Moroccan','{lunch,dinner}','🍅',2,12,25,'easy',
 '[{"name":"Minced beef","amount":"300 g","category":"Meat"},{"name":"Chopped tomatoes","amount":"400 g","category":"Pantry"},{"name":"Onion","amount":"1 pc","category":"Produce"},{"name":"Eggs","amount":"2 pc","category":"Dairy"},{"name":"Parsley & coriander","amount":"20 g","category":"Produce"},{"name":"Cumin","amount":"5 g","category":"Spices"},{"name":"Paprika","amount":"5 g","category":"Spices"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Khobz bread","amount":"150 g","category":"Bakery"}]'::jsonb,
 '["Mix the mince with half the herbs, the cumin and salt. Roll small meatballs.","Soften the onion in the oil, add paprika and the tomatoes, simmer 10 minutes.","Slip the meatballs in, cover and cook 12 minutes, turning once.","Crack the eggs on top, cover until just set. Scatter the rest of the herbs and mop up with khobz."]'::jsonb,
 610,44,38,30,5,'{"family","one pot"}',true,'Small meatballs cook faster and soak up more sauce.'),
('turkey-vegetable-couscous','Turkey & Vegetable Couscous','Lean turkey with the Friday vegetables','Moroccan','{lunch,dinner}','🥘',2,15,30,'easy',
 '[{"name":"Turkey breast","amount":"350 g","category":"Meat"},{"name":"Couscous","amount":"180 g","category":"Bakery"},{"name":"Carrots","amount":"200 g","category":"Produce"},{"name":"Courgette","amount":"200 g","category":"Produce"},{"name":"Chickpeas","amount":"150 g","category":"Pantry"},{"name":"Onion","amount":"1 pc","category":"Produce"},{"name":"Ras el hanout","amount":"8 g","category":"Spices"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Water","amount":"400 ml","category":"Pantry"}]'::jsonb,
 '["Brown the turkey pieces with the onion in the oil.","Add spices, water, carrots and chickpeas. Simmer 15 minutes.","Add the courgette and cook 10 more minutes.","Pour boiling water over the couscous, cover 5 minutes, fluff with a fork and spoon the stew over."]'::jsonb,
 560,46,62,14,9,'{"lean","family"}',true,'Turkey stays tender if you take it off the heat as soon as the veg is soft.'),
('chicken-shawarma-bowl','Chicken Shawarma Bowl','Spiced chicken, rice and cucumber yoghurt','Mediterranean','{lunch,dinner}','🥙',2,12,20,'easy',
 '[{"name":"Chicken breast","amount":"350 g","category":"Meat"},{"name":"Rice","amount":"160 g","category":"Pantry"},{"name":"Cucumber","amount":"150 g","category":"Produce"},{"name":"Plain yoghurt","amount":"150 g","category":"Dairy"},{"name":"Tomato","amount":"150 g","category":"Produce"},{"name":"Garlic","amount":"2 pc","category":"Produce"},{"name":"Cumin","amount":"5 g","category":"Spices"},{"name":"Paprika","amount":"5 g","category":"Spices"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Lemon","amount":"1 pc","category":"Produce"}]'::jsonb,
 '["Toss the sliced chicken with cumin, paprika, garlic, oil and lemon.","Cook the rice in salted water.","Fry the chicken in a hot pan until browned at the edges, 8 minutes.","Stir grated cucumber into the yoghurt. Build the bowls with rice, chicken, tomato and the yoghurt."]'::jsonb,
 590,48,64,16,4,'{"high protein"}',true,'A squeeze of lemon at the very end wakes the whole bowl up.'),
('minced-chicken-courgette-skillet','Minced Chicken & Courgette Skillet','A one-pan mince with rice','Mediterranean','{lunch,dinner}','🍲',2,10,22,'easy',
 '[{"name":"Minced chicken","amount":"350 g","category":"Meat"},{"name":"Courgette","amount":"250 g","category":"Produce"},{"name":"Rice","amount":"150 g","category":"Pantry"},{"name":"Tomato","amount":"200 g","category":"Produce"},{"name":"Onion","amount":"1 pc","category":"Produce"},{"name":"Garlic","amount":"2 pc","category":"Produce"},{"name":"Turmeric","amount":"4 g","category":"Spices"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"}]'::jsonb,
 '["Cook the rice in salted water.","Brown the mince with the onion and garlic in the oil, breaking it up well.","Add turmeric, tomato and diced courgette, cover and cook 12 minutes.","Season, fold through the rice or serve it alongside."]'::jsonb,
 540,45,56,14,5,'{"quick","budget"}',true,'Mince browns better in a hot pan you do not stir too often.'),
('chicken-paprika-pasta','Chicken Paprika Pasta','Creamy-looking pasta without the cream','Mediterranean','{lunch,dinner}','🍝',2,8,20,'easy',
 '[{"name":"Chicken breast","amount":"320 g","category":"Meat"},{"name":"Pasta","amount":"180 g","category":"Pantry"},{"name":"Tomato","amount":"200 g","category":"Produce"},{"name":"Plain yoghurt","amount":"100 g","category":"Dairy"},{"name":"Garlic","amount":"2 pc","category":"Produce"},{"name":"Paprika","amount":"6 g","category":"Spices"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Parsley","amount":"15 g","category":"Produce"}]'::jsonb,
 '["Boil the pasta, keeping a cup of the water.","Fry the sliced chicken in the oil with the garlic and paprika until golden.","Add the tomato and a splash of pasta water, simmer 5 minutes.","Off the heat, stir in the yoghurt and the drained pasta. Finish with parsley."]'::jsonb,
 620,47,68,18,5,'{"quick"}',false,'Add the yoghurt off the heat so it stays smooth.'),
('turkey-kefta-batbout','Turkey Kefta Batbout','Little turkey patties in warm bread','Moroccan','{lunch}','🫓',2,12,15,'easy',
 '[{"name":"Minced turkey","amount":"320 g","category":"Meat"},{"name":"Batbout or pitta","amount":"2 pc","category":"Bakery"},{"name":"Onion","amount":"1 pc","category":"Produce"},{"name":"Parsley & coriander","amount":"20 g","category":"Produce"},{"name":"Cumin","amount":"5 g","category":"Spices"},{"name":"Paprika","amount":"4 g","category":"Spices"},{"name":"Tomato","amount":"150 g","category":"Produce"},{"name":"Plain yoghurt","amount":"80 g","category":"Dairy"},{"name":"Olive oil","amount":"10 ml","category":"Pantry"}]'::jsonb,
 '["Mix the turkey with grated onion, herbs, cumin, paprika and salt.","Shape into flat patties and fry in the oil, 4 minutes each side.","Warm the bread in the same pan.","Fill with the patties, sliced tomato and a spoon of yoghurt."]'::jsonb,
 500,45,44,16,5,'{"lean","quick"}',true,'Flat patties cook through without drying out.'),
('chicken-chickpea-bowl','Chicken & Chickpea Bowl','Harira flavours in a filling bowl','Moroccan','{lunch}','🥣',2,10,25,'easy',
 '[{"name":"Chicken breast","amount":"300 g","category":"Meat"},{"name":"Chickpeas","amount":"250 g","category":"Pantry"},{"name":"Chopped tomatoes","amount":"300 g","category":"Pantry"},{"name":"Celery","amount":"80 g","category":"Produce"},{"name":"Onion","amount":"1 pc","category":"Produce"},{"name":"Ras el hanout","amount":"7 g","category":"Spices"},{"name":"Parsley & coriander","amount":"20 g","category":"Produce"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Khobz bread","amount":"120 g","category":"Bakery"}]'::jsonb,
 '["Soften the onion and celery in the oil.","Add the diced chicken and spices, stir 3 minutes.","Add tomatoes and chickpeas with a splash of water, simmer 18 minutes.","Finish with the herbs and serve with khobz."]'::jsonb,
 570,48,56,16,11,'{"budget","high protein"}',true,'This one is even better the next day.'),
('lemon-chicken-bulgur','Lemon Garlic Chicken & Bulgur','Bright chicken with a herby grain salad','Mediterranean','{lunch,dinner}','🍋',2,12,20,'easy',
 '[{"name":"Chicken breast","amount":"340 g","category":"Meat"},{"name":"Bulgur","amount":"160 g","category":"Pantry"},{"name":"Cucumber","amount":"150 g","category":"Produce"},{"name":"Tomato","amount":"150 g","category":"Produce"},{"name":"Parsley","amount":"20 g","category":"Produce"},{"name":"Lemon","amount":"1 pc","category":"Produce"},{"name":"Garlic","amount":"2 pc","category":"Produce"},{"name":"Olive oil","amount":"15 ml","category":"Pantry"},{"name":"Cumin","amount":"4 g","category":"Spices"}]'::jsonb,
 '["Pour boiling water over the bulgur, cover 12 minutes, then fluff.","Rub the chicken with garlic, lemon, cumin and oil and fry 8 minutes until golden.","Toss the bulgur with diced cucumber, tomato, parsley and lemon juice.","Slice the chicken over the salad."]'::jsonb,
 580,49,60,16,7,'{"lean","high protein"}',true,'Let the chicken rest two minutes before slicing — it stays juicy.')
on conflict (slug) do nothing;